-- Chamber member auth schema + seed from WKCCActiveMembers MemberResource export
create extension if not exists citext;
create extension if not exists pgcrypto;

create table if not exists public.chamber_members (
  cm_id integer primary key,
  name text not null,
  display_name text not null,
  email citext,
  status text not null,
  level text,
  membership_established timestamptz,
  drop_date timestamptz,
  slug text,
  display_flags text not null default '',
  raw jsonb not null default '{}'::jsonb,
  synced_at timestamptz not null default now()
);

create index if not exists chamber_members_email_idx on public.chamber_members (email);
create index if not exists chamber_members_status_idx on public.chamber_members (status);

create table if not exists public.login_codes (
  id uuid primary key default gen_random_uuid(),
  email citext not null,
  code_hash text not null,
  expires_at timestamptz not null,
  attempts integer not null default 0,
  consumed_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists login_codes_email_created_idx on public.login_codes (email, created_at desc);

create table if not exists public.app_profiles (
  id uuid primary key default gen_random_uuid(),
  email citext not null unique,
  cm_id integer references public.chamber_members(cm_id) on delete set null,
  is_chamber_admin boolean not null default false,
  last_login_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.app_sessions (
  id uuid primary key default gen_random_uuid(),
  email citext not null,
  cm_id integer references public.chamber_members(cm_id) on delete set null,
  refresh_token_hash text not null unique,
  expires_at timestamptz not null,
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists app_sessions_email_idx on public.app_sessions (email);

-- RLS: deny direct client access; edge functions use service role
alter table public.chamber_members enable row level security;
revoke all on public.chamber_members from anon, authenticated;
alter table public.login_codes enable row level security;
revoke all on public.login_codes from anon, authenticated;
alter table public.app_profiles enable row level security;
revoke all on public.app_profiles from anon, authenticated;
alter table public.app_sessions enable row level security;
revoke all on public.app_sessions from anon, authenticated;

-- Seed active members from ChamberMaster export
on conflict (cm_id) do update set
  name = excluded.name,
  display_name = excluded.display_name,
  email = excluded.email,
  status = excluded.status,
  level = excluded.level,
  membership_established = excluded.membership_established,
  drop_date = excluded.drop_date,
  slug = excluded.slug,
  display_flags = excluded.display_flags,
  raw = excluded.raw,
  synced_at = excluded.synced_at;
